window.RP_SESSION={"id":"S-7112b92f0098","messages":[{"id":"RP-II-0023932","time":"2026-01-18T18:53:00+09:00","room":"RP II","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"이전에 라르손에게 받은 약병을 꺼내었습니다.... 물에 타 마시라 했것만, 그 말을 곧이곧대로 듣는 다면 그녀가 아니죠. 이내 사탕이라도 꺼내듯 마른 찻잎과 같은 것을 몇 개 손바닥 위에 털어놓곤 삼켰습니다. 노곤노곤한 이 기분이, 그저 좋을 뿐입니다.","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0023933","time":"2026-01-18T19:04:00+09:00","room":"RP II","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"약간 바삭한것이 식감도 꽤나 괜찮습니다. ..병을 살살 흔들어보았습니다. 이 약들도 금새 사라지겠죠. 나중에 찾아가 이번보다 더 얻어내야겠습니다.","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0023934","time":"2026-01-18T19:04:00+09:00","room":"RP II","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-c9505ea97ebc"]},{"id":"RP-II-0023935","time":"2026-01-18T19:04:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"다음을 기대할게..!","characters":[]}]};
